#!/usr/bin/env node
/**
 * Wrangler build hook for Cloudflare Workers Builds Git integrations.
 *
 * MotoIndex's production Worker is generated by OpenNext, not by "next build".
 * A dashboard using the default Next.js build command can leave
 * wrangler.jsonc.main (.open-next/worker.js) missing. Wrangler runs this build
 * hook before deploy, including when Workers Builds invokes Wrangler itself.
 *
 * The script is a no-op after a successful OpenNext build, so the reviewed
 * GitHub Actions deployment path retains its existing build artifact.
 *
 * Never invokes a deployment and never reads or prints credentials.
 */
import { existsSync, statSync } from "node:fs";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import { dirname, resolve } from "node:path";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const worker = resolve(root, ".open-next", "worker.js");
const nextBuildId = resolve(root, ".next", "BUILD_ID");
const npmCommand = process.platform === "win32" ? "npm.cmd" : "npm";

function isWorkerReady() {
  return existsSync(worker) && statSync(worker).size > 0;
}
function run(command, args) {
  const result = spawnSync(command, args, {
    cwd: root,
    stdio: "inherit",
    env: { ...process.env, MOTOINDEX_CF_BUILD_GUARD: "1" }
  });
  if (result.error) throw result.error;
  if (result.status !== 0) {
    throw new Error("Cloudflare OpenNext build failed (" + command +
      " exit " + String(result.status) + "). Review the build logs.");
  }
}

if (isWorkerReady()) {
  console.log("[MotoIndex] OpenNext Worker exists; skipping duplicate build.");
} else {
  if (process.env.MOTOINDEX_CF_BUILD_GUARD === "1") {
    throw new Error(
      "Recursive Cloudflare build hook detected. Ensure npm run build only runs Next.js and cf:build uses OpenNext."
    );
  }
  if (existsSync(nextBuildId)) {
    console.log("[MotoIndex] Converting existing Next.js output to the Cloudflare Worker with OpenNext.");
    // The dashboard may have already run "npm run build" (Next.js only).
    // Reuse its build output rather than repeating a potentially costly build.
    run(npmCommand, ["exec", "--", "opennextjs-cloudflare", "build", "--skipNextBuild"]);
  } else {
    console.log("[MotoIndex] No Next.js or OpenNext output exists; running the full Cloudflare adapter build.");
    run(npmCommand, ["run", "cf:build"]);
  }
  if (!isWorkerReady()) {
    throw new Error(
      "OpenNext finished without .open-next/worker.js. Check the adapter version and Cloudflare build command."
    );
  }
  console.log("[MotoIndex] OpenNext Worker verified for Wrangler.");
}
